#!/bin/bash
# GENERATED by tools/host_leaf_suite.py gen-script leaf_hw_free_b - edit the @leaf
# markers in leaf_hw_free_b_harness.c, not this file.
# Compiles the unchanged decomp units below, links them with the leaf harness
# and runs the per-function checks under QEMU.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
DECOMP="${DECOMP:-$(cd "$HERE/../.." && pwd)}"
T="${TOOLCHAIN:-$DECOMP/.toolchain}"
OUT="${OUT:-$HERE/build-leaf-hw-free-b}"
QEMU="${QEMU:-$HOME/.local/share/qemu-user/extracted/usr/bin/qemu-mipsel}"
GCC="$T/gcc-2.7.2-cdk/gcc"
MASPSX="$(echo "$T"/maspsx-*/maspsx.py)"
mkdir -p "$OUT"
export PATH="$T/mipsel-binutils/root/usr/bin:$PATH"
export LD_LIBRARY_PATH="$T/mipsel-binutils/root/usr/lib/x86_64-linux-gnu${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"

compile() {
    local src="$1" obj="$2"; shift 2
    "$GCC" -B"$T/gcc-2.7.2-cdk/" -I"$DECOMP/include" -I"$HERE/mocks" "$@" -O1 -G0 -S "$src" -o "$OUT/tmp.s"
    python3 "$MASPSX" "$OUT/tmp.s" | python3 "$HERE/fix_align.py" > "$OUT/tmp.mas.s"
    mipsel-linux-gnu-as -o "$obj" "$OUT/tmp.mas.s"
}

objects=()
for unit in 8001306C 80045494 8009398C 80093AF0 80044988 8004DA84 8004DC64 8006F170 80029520 80069B58 80031990 8003FD74 80073500 80073590 800834C4 8005A220 800860CC 80086164 800427E8 80071A68 80045678 800457B8 8005A6A4 800753D0 8007A3AC 80093F58 80093F78 80094010 800940A8 800940C4 800448D8 8003BF1C 80069B1C 800455DC 8005A654 8004DA58 8004D9EC; do
    compile "$DECOMP/src/game/$unit.c" "$OUT/$unit.o"
    objects+=("$OUT/$unit.o")
done
compile "$HERE/mocks/bios_mock.c" "$OUT/bios_mock.o"
compile "$HERE/mocks/sound_mock.c" "$OUT/sound_mock.o"
python3 "$HERE/leaf_vectors.py" > "$OUT/leaf_vectors.h"
compile "$HERE/leaf_hw_free_b_harness.c" "$OUT/leaf_hw_free_b_harness.o" -I"$OUT" -I"$HERE"
mipsel-linux-gnu-as -o "$OUT/crt0.o" "$HERE/crt0.s" 2>/dev/null
mipsel-linux-gnu-ld -static -e __start -o "$OUT/leaf_hw_free_b" \
    "$OUT/crt0.o" "$OUT/leaf_hw_free_b_harness.o" "$OUT/bios_mock.o" "$OUT/sound_mock.o" "${objects[@]}"
"$QEMU" "$OUT/leaf_hw_free_b"
